-- Ejecutar tras desplegar las imágenes del PR y verificar su disponibilidad.
BEGIN;
DO $block$
DECLARE n integer; expected jsonb := $payload$[{"id":"9ce2bc98-abfe-5507-8f54-4c062c9d7f90","language":"de","public_path":"/de/mini-quiches-mit-spinat-und-feta","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Lege die Mulden aus","content":"Lege die 12 kalten Teigkreise in ein Muffinblech und drücke sie ohne Dehnen an Boden und Rand.","image_alt":"Zwölf Mulden eines dunklen Muffinblechs mit rohem Blätterteig, noch ohne Füllung.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Dünste den Spinat","content":"Gare 300 g Spinat mit 10 g Öl bei mittlerer Hitze 3–4 Minuten in einer Pfanne. Rühre, bis die Blätter zusammenfallen und kein freies Wasser mehr in der Pfanne steht.","image_alt":"Zusammengefallener, glänzender Spinat in einer schwarzen Pfanne mit Holzlöffel.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Drücke den Spinat aus","content":"Drücke den gegarten Spinat mit einem Löffelrücken in einem Sieb aus.","image_alt":"Gegarter Spinat in einem Metallsieb über einer weißen Schüssel mit abgetropfter Flüssigkeit.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Vermische die Füllung","content":"Vermische 150 g Ei mit Sahne, Milch, Feta, ausgedrücktem Spinat, Pfeffer und Muskat. Rühre nur bis alles verteilt ist; schlage die Masse nicht auf und gib kein Salz dazu.","image_alt":"Glasschüssel mit flüssiger Eier-Sahne-Mischung, Spinat und weißen Fetastücken.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Fülle die Böden","content":"Verteile die Füllung auf die 12 Teigböden und fülle sie zu drei Vierteln. Verteile Spinat und Feta gleichmäßig, damit alle Quiches ähnlich gefüllt sind.","image_alt":"Zwölf rohe Blätterteigböden, zu drei Vierteln mit Spinat-Feta-Eiermasse gefüllt.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Backe die Quiches","content":"Backe im unteren Ofendrittel bei vorgeheizten 190 °C Ober-/Unterhitze 25–30 Minuten. Der Teig muss goldbraun werden und die Füllung im Kern mindestens 71 °C erreichen.","image_alt":"Goldbraun werdende Spinat-Feta-Quiches im dunklen Muffinblech im Backofen.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Lass sie ruhen","content":"Lass die Quiches im Blech auf einem Kuchengitter 10 Minuten ruhen. So setzt sich die Füllung und die Böden lassen sich leichter unbeschädigt lösen.","image_alt":"Zwölf gebackene Mini-Quiches ruhen im Muffinblech auf einem Metallgitter.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Serviere die Quiches","content":"Serviere die Mini-Quiches lauwarm, je zwei Stück pro Portion. Die Füllung soll gestockt und saftig sein, der Blätterteig auch an der Unterseite goldbraun.","image_alt":"Goldene Mini-Quiches auf einem cremefarbenen Teller, eine geöffnet mit Spinat-Feta-Füllung.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Ja, verwende 150 g nach dem Auftauen und Ausdrücken. Gemeint ist das Gewicht ohne abgetropfte Flüssigkeit.","q":"Kann ich TK-Spinat verwenden?"},{"a":"Für diese kleinen Quiches nicht. Dünne Böden, gut abgetropfte Füllung und das untere Drittel des vorgeheizten Ofens helfen beim Durchbacken.","q":"Muss ich den Teig vorbacken?"},{"a":"Häufig sind schlecht ausgedrückter Spinat, zu dicker Teig oder ein nicht vorgeheizter Ofen die Ursache. Fülle die Mulden nicht randvoll.","q":"Warum sind die Böden feucht?"}],"title":"Mini-Quiches mit Spinat und Feta aus Blätterteig","image_alt":"Goldene Mini-Quiches auf einem cremefarbenen Teller, eine geöffnet mit Spinat-Feta-Füllung.","description":"Backe 12 Mini-Quiches mit Spinat, Feta und Blätterteig. Acht bebilderte Schritte sowie Tipps für cremige Füllung und goldbraune Böden.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Schätzung für zwei Quiches; die Marken von Blätterteig, Sahne und Feta beeinflussen die Werte. Beilagen sind nicht enthalten.","fat_g":38.2,"method":"Nährwerte nach Zutatengewicht summiert und durch 6 Portionen geteilt; Milch und Sahne mit etwa 1 g/ml berechnet.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 Mini-Quiches (1/6 des Rezepts)","saturated_fat_g":15.3},"notes":"<h3>Tipps</h3><p>Verwende Teigkreise von etwa 25 g und halte sie kalt. Heize den Ofen während der Füllungszubereitung vor. Feta liefert ausreichend Salz. Aus Gründen der Lebensmittelsicherheit muss die Eierfüllung im Kern 71 °C erreichen.</p><h3>Alternativen</h3><p>Statt frischem Spinat eignen sich 150 g tiefgekühlter Spinat, nach dem Auftauen und gründlichen Ausdrücken gewogen. Fester Ziegenkäse kann Feta ersetzen; sein Salzgehalt ist anders.</p><h3>Aufbewahrung</h3><p>Innerhalb von 2 Stunden in einem geschlossenen Behälter bei höchstens 4 °C kühlen und 3–4 Tage aufbewahren. Beim Aufwärmen im Kern 74 °C erreichen; im Ofen wird der Teig wieder knuspriger.</p><p class=\"md-sources\">Quellen: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Lass den ausgedrückten Spinat vor dem Vermischen mit dem Ei lauwarm werden.</p>"},{"id":"037f2cb4-1934-5a21-8d0c-91bc3a0d8e60","language":"en","public_path":"/en/mini-spinach-feta-puff-pastry-quiches","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Line the tin","content":"Fit the 12 cold pastry discs into a metal muffin tin, pressing them gently against the bases and sides without stretching.","image_alt":"Twelve cups of a dark muffin tin lined with raw puff pastry discs, without filling.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Wilt the spinach","content":"Cook 300 g spinach with 10 g oil in a frying pan over medium heat for 3–4 minutes. Stir until the leaves collapse and no loose water remains in the pan.","image_alt":"Wilted glossy spinach in a black frying pan with a wooden spoon.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Drain the spinach","content":"Press the cooked spinach in a sieve with the back of a spoon to remove excess liquid.","image_alt":"Cooked spinach pressed in a metal sieve over a white bowl containing drained liquid.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Mix the filling","content":"Mix 150 g egg with the cream, milk, feta, drained spinach, pepper and nutmeg. Stir only until evenly combined; do not whip the mixture or add salt.","image_alt":"Glass bowl containing liquid egg and dairy mixture with spinach and white feta pieces.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Fill the cases","content":"Divide the filling among the 12 pastry cases, filling each three-quarters full. Distribute the spinach and feta evenly so each quiche has a similar balance.","image_alt":"Twelve raw pastry cases filled three-quarters full with liquid spinach and feta custard.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Bake the quiches","content":"Bake in the lower third of an oven preheated to 190 °C (375 °F), conventional heat, for 25–30 minutes. The pastry should be golden and the filling must reach at least 71 °C (160 °F).","image_alt":"Spinach and feta mini quiches turning golden in a dark muffin tin inside an oven.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Let them rest","content":"Rest the quiches in their tin on a wire rack for 10 minutes. This lets the filling settle and helps the pastry release without breaking.","image_alt":"Twelve baked mini quiches resting in their muffin tin on a metal cooling rack.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Serve the quiches","content":"Serve the mini quiches warm, allowing two per person. The filling should be set but moist, with golden pastry underneath as well as around the edges.","image_alt":"Golden mini quiches on a cream ceramic plate, one opened to reveal set spinach and feta filling.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Yes. Use 150 g after thawing and squeezing. This is the weight of spinach going into the filling, without the drained liquid.","q":"Can I use frozen spinach?"},{"a":"Not for these small quiches. Use thin discs, well-drained filling and the lower third of a preheated oven to help cook the bases.","q":"Do I need to blind-bake the pastry?"},{"a":"Poorly drained spinach, thick pastry or an oven that was not preheated are common causes. Avoid filling the cases to the brim.","q":"Why are the bases soggy?"}],"title":"Mini spinach and feta quiches with puff pastry","image_alt":"Golden mini quiches on a cream ceramic plate, one opened to reveal set spinach and feta filling.","description":"Make 12 mini spinach and feta quiches with golden puff pastry. Eight illustrated steps, a creamy filling and practical baking and storage tips.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Estimate per two-quiche serving; puff pastry, cream and feta brands affect the values. Side dishes are not included.","fat_g":38.2,"method":"Ingredient nutrients summed by weight and divided by 6 servings; milk and cream approximated at 1 g/ml.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 mini quiches (1/6 of the recipe)","saturated_fat_g":15.3},"notes":"<h3>Tips</h3><p>Use pastry discs weighing about 25 g and keep them cold. Preheat the oven while making the filling. Feta supplies enough salt. For food safety, the egg filling must reach 71 °C (160 °F) in the centre.</p><h3>Substitutions</h3><p>You can replace the fresh spinach with 150 g frozen spinach weighed after thawing and squeezing very well. Firm goat cheese can replace feta, though its salt content differs.</p><h3>Storage</h3><p>Refrigerate in a closed container within 2 hours at 4 °C (40 °F) or below for 3–4 days. Reheat to 74 °C (165 °F) in the centre; an oven helps crisp the pastry again.</p><p class=\"md-sources\">Sources: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Let the drained spinach cool to lukewarm before mixing it with the egg.</p>"},{"id":"9ed175a9-578c-4a9d-bae2-b7d8c27c83b1","language":"es","public_path":"/mini-quiches-de-espinaca-y-queso-feta","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Forra el molde","content":"Acomoda los 12 discos de hojaldre frío en las cavidades de un molde metálico para muffins, ajustándolos a la base y los lados sin estirarlos.","image_alt":"Doce cavidades de un molde oscuro forradas con discos de hojaldre crudo, todavía sin relleno.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Saltea la espinaca","content":"Cocina los 300 g de espinaca con los 10 g de aceite en una sartén a fuego medio durante 3–4 minutos. Remueve hasta que las hojas pierdan volumen y no quede agua libre en la sartén.","image_alt":"Espinacas reducidas y brillantes en una sartén negra con una cuchara de madera.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Escurre la espinaca","content":"Presiona la espinaca cocida en un colador con el dorso de una cuchara para eliminar el líquido.","image_alt":"Espinaca cocida presionada en un colador metálico sobre un cuenco blanco con líquido escurrido.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Mezcla el relleno","content":"Mezcla los 150 g de huevo con la nata, la leche, el feta, la espinaca escurrida, la pimienta y la nuez moscada. Trabaja solo hasta repartir los ingredientes, sin montar ni añadir sal.","image_alt":"Cuenco de vidrio con huevo y lácteos líquidos, espinaca escurrida y trozos blancos de feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Rellena las bases","content":"Reparte el relleno entre las 12 bases de hojaldre, hasta tres cuartos de su altura. Distribuye de forma uniforme los trozos de feta y la espinaca para que todas las quiches tengan la misma proporción.","image_alt":"Doce bases de hojaldre crudo con relleno líquido de huevo, feta y espinaca hasta tres cuartos.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Hornea las quiches","content":"Hornea en el tercio inferior del horno ya precalentado a 190 °C, con calor arriba y abajo, durante 25–30 minutos. El hojaldre debe dorarse y el centro del relleno alcanzar al menos 71 °C.","image_alt":"Mini quiches de espinaca y feta dorándose dentro del horno en un molde oscuro de muffins.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Deja reposar","content":"Deja las quiches en el molde sobre una rejilla durante 10 minutos. Este reposo permite que el relleno se asiente y que las bases se desprendan sin romperse.","image_alt":"Doce mini quiches horneadas descansando dentro del molde sobre una rejilla metálica.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Sirve las quiches","content":"Sirve las mini quiches templadas, con dos unidades por ración. El relleno debe estar cuajado y jugoso, y el hojaldre dorado también en la base.","image_alt":"Mini quiches doradas en un plato de cerámica crema, una abierta mostrando espinaca y feta cuajados.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Sí. Usa 150 g una vez descongelada y escurrida. El peso corresponde a la espinaca que entra en el relleno, sin el líquido.","q":"¿Se puede usar espinaca congelada?"},{"a":"No en estas piezas pequeñas. Usa discos finos, relleno bien escurrido y el tercio inferior del horno precalentado para favorecer la cocción de la base.","q":"¿Hay que hornear el hojaldre antes?"},{"a":"Suele deberse a espinaca mal escurrida, masa demasiado gruesa o un horno sin precalentar. También conviene evitar llenar las cavidades hasta el borde.","q":"¿Por qué quedan húmedas por debajo?"}],"title":"Mini quiches de espinaca y feta con hojaldre","image_alt":"Mini quiches doradas en un plato de cerámica crema, una abierta mostrando espinaca y feta cuajados.","description":"Prepara mini quiches de espinaca y feta con hojaldre: 12 unidades, ocho pasos con fotos y consejos para un relleno cremoso y una base dorada.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Estimación por ración de dos unidades; varía con la marca de hojaldre, la nata y el feta. No incluye acompañamientos.","fat_g":38.2,"method":"Suma de nutrientes de los pesos de ingredientes, dividida entre 6 raciones; leche y nata aproximadas a 1 g/ml.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 mini quiches (1/6 de la receta)","saturated_fat_g":15.3},"notes":"<h3>Consejos</h3><p>Usa discos de hojaldre de unos 25 g y mantén la masa fría. Precalienta el horno mientras preparas el relleno. El feta ya aporta sal; no es necesario añadir más. Por seguridad, el relleno de huevo debe alcanzar 71 °C en el centro.</p><h3>Sustituciones</h3><p>Puedes usar 150 g de espinaca congelada ya descongelada y muy bien escurrida en lugar de la espinaca fresca. Sustituye el feta por queso de cabra firme si prefieres otro sabor; cambia el contenido de sal.</p><h3>Conservación</h3><p>Refrigera en un recipiente cerrado antes de 2 horas, a 4 °C o menos, durante 3–4 días. Recalienta hasta 74 °C en el centro; el horno ayuda a recuperar el hojaldre crujiente.</p><p class=\"md-sources\">Fuentes: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Deja templar la espinaca escurrida antes de mezclarla con el huevo.</p>"},{"id":"d78fdc34-ae5a-5655-ae03-bdddae5bf59f","language":"fr","public_path":"/fr/mini-quiches-epinards-feta-pate-feuilletee","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Foncez les empreintes","content":"Garnissez les 12 cavités d’un moule à muffins métallique avec les disques de pâte froide, sans les étirer.","image_alt":"Douze empreintes d’un moule sombre garnies de pâte feuilletée crue, encore vides.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Faites tomber les épinards","content":"Faites cuire les 300 g d’épinards avec les 10 g d’huile à feu moyen pendant 3–4 minutes. Remuez jusqu’à ce que les feuilles réduisent et qu’il ne reste plus d’eau libre dans la poêle.","image_alt":"Épinards cuits et brillants dans une poêle noire avec une cuillère en bois.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Pressez les épinards","content":"Pressez les épinards cuits dans une passoire avec le dos d’une cuillère pour retirer le liquide.","image_alt":"Épinards cuits pressés dans une passoire métallique au-dessus d’un bol blanc contenant le jus.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Mélangez la garniture","content":"Mélangez les 150 g d’œuf avec la crème, le lait, la feta, les épinards égouttés, le poivre et la muscade. Répartissez simplement les ingrédients, sans fouetter pour faire mousser ni ajouter de sel.","image_alt":"Saladier en verre contenant un mélange liquide d’œufs et de crème avec épinards et feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Garnissez les fonds","content":"Répartissez la garniture dans les 12 fonds de pâte jusqu’aux trois quarts de leur hauteur. Distribuez régulièrement les épinards et les morceaux de feta.","image_alt":"Douze fonds de pâte crue remplis aux trois quarts de garniture liquide aux épinards et feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Faites cuire les quiches","content":"Enfournez dans le tiers inférieur du four préchauffé à 190 °C, en chaleur statique, pendant 25–30 minutes. La pâte doit dorer et le cœur de la garniture atteindre au moins 71 °C.","image_alt":"Mini quiches aux épinards et feta dorant dans un moule sombre à l’intérieur du four.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Laissez reposer","content":"Laissez les quiches dans leur moule posé sur une grille pendant 10 minutes. La garniture se stabilise et les fonds se démoulent plus facilement sans se casser.","image_alt":"Douze mini quiches cuites reposant dans leur moule sur une grille métallique.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Servez les quiches","content":"Servez les mini quiches tièdes, à raison de deux par personne. La garniture doit être prise mais moelleuse, et la pâte dorée également sous les quiches.","image_alt":"Mini quiches dorées sur une assiette crème, une ouverte montrant la garniture prise aux épinards et feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Oui, utilisez 150 g après décongélation et essorage. Ce poids correspond aux épinards ajoutés à la garniture, sans le liquide.","q":"Peut-on utiliser des épinards surgelés ?"},{"a":"Pas pour ces petites quiches. Utilisez des disques fins, une garniture bien égouttée et le tiers inférieur d’un four préchauffé.","q":"Faut-il précuire la pâte ?"},{"a":"Des épinards mal essorés, une pâte épaisse ou un four non préchauffé peuvent en être la cause. Ne remplissez pas les empreintes à ras bord.","q":"Pourquoi les fonds sont-ils humides ?"}],"title":"Mini quiches aux épinards et feta en pâte feuilletée","image_alt":"Mini quiches dorées sur une assiette crème, une ouverte montrant la garniture prise aux épinards et feta.","description":"Réalisez 12 mini quiches aux épinards et feta avec une pâte feuilletée dorée. Huit étapes illustrées et des conseils de cuisson et conservation.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Estimation pour deux quiches ; les marques de pâte, crème et feta modifient les valeurs. Accompagnements exclus.","fat_g":38.2,"method":"Somme des nutriments selon le poids des ingrédients, divisée par 6 portions ; lait et crème approximés à 1 g/ml.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 mini quiches (1/6 de la recette)","saturated_fat_g":15.3},"notes":"<h3>Conseils</h3><p>Utilisez des disques de pâte d’environ 25 g et gardez-les froids. Préchauffez le four pendant la préparation. La feta apporte assez de sel. Pour la sécurité alimentaire, le cœur de la garniture aux œufs doit atteindre 71 °C.</p><h3>Remplacements</h3><p>Vous pouvez remplacer les épinards frais par 150 g d’épinards surgelés pesés après décongélation et essorage soigneux. Un fromage de chèvre ferme remplace la feta, mais sa teneur en sel diffère.</p><h3>Conservation</h3><p>Réfrigérez dans un récipient fermé avant 2 heures, à 4 °C ou moins, pendant 3–4 jours. Réchauffez jusqu’à 74 °C à cœur ; le four aide à rendre le feuilletage croustillant.</p><p class=\"md-sources\">Sources: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Laissez tiédir les épinards égouttés avant de les mélanger aux œufs.</p>"},{"id":"2ca3132c-b1e9-5559-8ac1-57e51c682bb6","language":"it","public_path":"/it/mini-quiche-spinaci-feta-pasta-sfoglia","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Rivesti lo stampo","content":"Rivesti le 12 cavità di uno stampo metallico da muffin con i dischi di sfoglia freddi, senza tirare la pasta.","image_alt":"Dodici cavità di uno stampo scuro rivestite con pasta sfoglia cruda, ancora senza ripieno.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Cuoci gli spinaci","content":"Cuoci i 300 g di spinaci con i 10 g d’olio in padella a fuoco medio per 3–4 minuti. Mescola finché le foglie si riducono e non rimane acqua libera nella padella.","image_alt":"Spinaci appassiti e lucidi in una padella nera con un cucchiaio di legno.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Strizza gli spinaci","content":"Premi gli spinaci cotti in un colino con il dorso di un cucchiaio per eliminare il liquido.","image_alt":"Spinaci cotti pressati in un colino metallico sopra una ciotola bianca con il liquido scolato.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Mescola il ripieno","content":"Mescola i 150 g d’uovo con panna, latte, feta, spinaci scolati, pepe e noce moscata. Lavora solo fino a distribuire gli ingredienti, senza montare né aggiungere sale.","image_alt":"Ciotola di vetro con composto liquido di uova e latticini, spinaci e pezzetti bianchi di feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Riempi i gusci","content":"Distribuisci il ripieno nei 12 gusci di sfoglia, riempiendoli per tre quarti. Ripartisci in modo uniforme spinaci e feta, così ogni quiche avrà un ripieno equilibrato.","image_alt":"Dodici gusci di sfoglia cruda riempiti per tre quarti con composto liquido di spinaci e feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Inforna le quiche","content":"Cuoci nel terzo inferiore del forno già caldo a 190 °C, statico, per 25–30 minuti. La sfoglia deve dorarsi e il centro del ripieno raggiungere almeno 71 °C.","image_alt":"Mini quiche di spinaci e feta che dorano nello stampo scuro dentro il forno.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Lascia riposare","content":"Lascia riposare le quiche nello stampo appoggiato su una griglia per 10 minuti. Il ripieno si assesta e i gusci si staccano più facilmente senza rompersi.","image_alt":"Dodici mini quiche cotte a riposo nello stampo su una griglia metallica.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Servi le quiche","content":"Servi le mini quiche tiepide, due per porzione. Il ripieno deve essere rappreso ma morbido e la sfoglia dorata anche sul fondo.","image_alt":"Mini quiche dorate su un piatto color crema, una aperta con ripieno cotto di spinaci e feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Sì, usane 150 g dopo averli scongelati e strizzati. Il peso riguarda gli spinaci da mettere nel ripieno, senza il liquido.","q":"Posso usare spinaci surgelati?"},{"a":"Non per queste piccole quiche. Usa dischi sottili, ripieno ben scolato e il terzo inferiore del forno preriscaldato.","q":"Devo precuocere la sfoglia?"},{"a":"Le cause comuni sono spinaci poco strizzati, pasta spessa o forno non preriscaldato. Evita anche di riempire le cavità fino all’orlo.","q":"Perché il fondo è umido?"}],"title":"Mini quiche di spinaci e feta con pasta sfoglia","image_alt":"Mini quiche dorate su un piatto color crema, una aperta con ripieno cotto di spinaci e feta.","description":"Prepara 12 mini quiche di spinaci e feta con sfoglia dorata. Otto passaggi illustrati, ripieno cremoso e consigli per cottura e conservazione.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Stima per due quiche; i valori cambiano con la marca di sfoglia, panna e feta. Contorni esclusi.","fat_g":38.2,"method":"Somma dei nutrienti in base al peso degli ingredienti, divisa per 6 porzioni; latte e panna approssimati a 1 g/ml.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 mini quiche (1/6 della ricetta)","saturated_fat_g":15.3},"notes":"<h3>Consigli</h3><p>Usa dischi di sfoglia da circa 25 g e mantienili freddi. Preriscalda il forno mentre prepari il ripieno. La feta apporta già sale. Per sicurezza alimentare, il ripieno di uova deve raggiungere 71 °C al centro.</p><h3>Sostituzioni</h3><p>Puoi sostituire gli spinaci freschi con 150 g di spinaci surgelati pesati dopo scongelamento e accurata strizzatura. Un caprino compatto può sostituire la feta, ma cambia la quantità di sale.</p><h3>Conservazione</h3><p>Metti in frigorifero in un contenitore chiuso entro 2 ore, a 4 °C o meno, per 3–4 giorni. Riscalda fino a 74 °C al centro; il forno aiuta a rendere di nuovo croccante la sfoglia.</p><p class=\"md-sources\">Fonti: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Lascia intiepidire gli spinaci scolati prima di mescolarli alle uova.</p>"},{"id":"b8a5e32b-ca1c-5ae1-843b-177740e25b8d","language":"ja","public_path":"/ja/ほうれん草とフェタのミニキッシュ","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"型に生地を敷く","content":"冷たいパイ生地の円形12枚を、伸ばさずに金属製マフィン型の底と側面に敷きます。","image_alt":"濃い色のマフィン型の12穴に、まだ中身のない生のパイ生地を敷いた状態。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"ほうれん草を炒める","content":"ほうれん草300 gをオイル10 gで、中火で3–4分炒めます。葉がしんなりし、フライパンに余分な水が残らなくなるまで混ぜながら加熱します。","image_alt":"黒いフライパンでしんなりしたつやのあるほうれん草と木べら。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"ほうれん草を絞る","content":"加熱したほうれん草をざるに入れ、スプーンの背で押して水気を切ります。","image_alt":"白いボウルの上の金属ざるで、加熱したほうれん草の水分を絞っている状態。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"卵液を混ぜる","content":"卵150 gに生クリーム、牛乳、フェタ、絞ったほうれん草、こしょう、ナツメグを混ぜます。均一に分散するまでにとどめ、泡立てず、塩も加えません。","image_alt":"ガラスのボウルに入った液状の卵と乳製品、ほうれん草、白いフェタのかけら。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"生地に詰める","content":"12個の生地に卵液を高さの4分の3まで均等に分けます。ほうれん草とフェタも、どのキッシュにも同じくらい入るようにします。","image_alt":"12個の生のパイ生地に、ほうれん草とフェタ入りの卵液を4分の3まで詰めた状態。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"キッシュを焼く","content":"190 °Cに予熱した上下加熱のオーブンの下段で25–30分焼きます。生地をきつね色にし、フィリングの中心温度を少なくとも71 °Cにします。","image_alt":"オーブン内の濃い色の型で、ほうれん草とフェタのミニキッシュが焼けている様子。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"型の中で休ませる","content":"型を金網に置き、キッシュを入れたまま10分休ませます。卵液が落ち着き、生地を崩さずに型から外しやすくなります。","image_alt":"焼き上がった12個のミニキッシュを型に入れたまま金網で休ませている状態。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"キッシュを盛り付ける","content":"温かいミニキッシュを1人2個ずつ盛り付けます。中は固まりつつしっとりしていて、生地は底まできつね色に焼けているのが目安です。","image_alt":"クリーム色の皿に盛ったミニキッシュ。ひとつを開き、固まったほうれん草とフェタの中身が見える。","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"はい。解凍してしっかり絞った状態で150 g使います。水分を除いてフィリングに入れる分の重さです。","q":"冷凍ほうれん草は使えますか？"},{"a":"この小さなキッシュでは不要です。薄い生地と水切りしたフィリングを使い、予熱したオーブンの下段で焼きます。","q":"生地の空焼きは必要ですか？"},{"a":"ほうれん草の絞り不足、生地が厚すぎる、予熱不足などが主な原因です。型いっぱいまで詰めるのも避けてください。","q":"底が湿るのはなぜですか？"}],"title":"ほうれん草とフェタのミニキッシュ、パイ生地で12個","image_alt":"クリーム色の皿に盛ったミニキッシュ。ひとつを開き、固まったほうれん草とフェタの中身が見える。","description":"マフィン型で作るほうれん草とフェタのミニキッシュ。12個分の材料と写真付き8工程で、香ばしいパイ生地としっとりした卵のフィリングに仕上げます。焼き方と保存のコツも紹介。","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"2個分の推定値です。パイ生地、生クリーム、フェタの製品によって変わります。付け合わせは含みません。","fat_g":38.2,"method":"材料の重量に応じた栄養量を合計し、6人分で割った値。牛乳と生クリームは1 mlを約1 gとして計算。","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"ミニキッシュ2個（全量の1/6）","saturated_fat_g":15.3},"notes":"<h3>コツ</h3><p>生地は1枚約25 gを目安にし、冷たいまま扱います。フィリングを作る間にオーブンを予熱してください。フェタに塩分があるため追加の塩は不要です。食品の安全のため、卵のフィリングは中心温度71 °Cまで加熱します。</p><h3>代用</h3><p>生のほうれん草の代わりに、解凍して十分に絞った冷凍ほうれん草150 gを使えます。フェタは固めの山羊乳チーズでも代用できますが、塩分量は変わります。</p><h3>保存</h3><p>2時間以内に密閉容器に入れて4 °C以下で冷蔵し、3–4日以内に食べます。温め直すときは中心を74 °Cにしてください。オーブンを使うと生地の香ばしさが戻りやすくなります。</p><p class=\"md-sources\">出典: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>水気を切ったほうれん草は、人肌程度に冷ましてから卵と混ぜます。</p>"},{"id":"5a8b84a9-5a71-5d9f-a3c7-8aff462e0fd9","language":"pt","public_path":"/pt/miniquiches-de-espinafre-e-feta-com-massa-folhada","updated_at":"2026-10-12T22:50:15.648174+00:00","steps":[{"title":"Forre a forma","content":"Forre as 12 cavidades de uma forma metálica de muffins com os discos de massa frios, sem esticar.","image_alt":"Doze cavidades de uma forma escura forradas com discos de massa folhada crua, sem recheio.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-01.webp"},{"title":"Refogue o espinafre","content":"Cozinhe os 300 g de espinafre com os 10 g de azeite em fogo médio por 3–4 minutos. Mexa até as folhas murcharem e não restar água livre na frigideira.","image_alt":"Espinafre murcho e brilhante em uma frigideira preta com colher de madeira.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-02.webp"},{"title":"Esprema o espinafre","content":"Pressione o espinafre cozido em uma peneira com as costas de uma colher para retirar o líquido.","image_alt":"Espinafre cozido pressionado em uma peneira metálica sobre uma tigela branca com líquido escorrido.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-03.webp"},{"title":"Misture o recheio","content":"Misture os 150 g de ovo com creme de leite, leite, feta, espinafre escorrido, pimenta e noz-moscada. Mexa só até distribuir os ingredientes, sem bater para aerar nem acrescentar sal.","image_alt":"Tigela de vidro com mistura líquida de ovos e laticínios, espinafre e pedaços brancos de feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-04.webp"},{"title":"Recheie as bases","content":"Distribua o recheio entre as 12 bases de massa, até três quartos da altura. Reparta o espinafre e o feta por igual para que todas tenham uma proporção semelhante.","image_alt":"Doze bases de massa crua preenchidas até três quartos com recheio líquido de espinafre e feta.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-05.webp"},{"title":"Asse as quiches","content":"Asse no terço inferior do forno preaquecido a 190 °C, com calor superior e inferior, por 25–30 minutos. A massa deve dourar e o centro do recheio atingir pelo menos 71 °C.","image_alt":"Miniquiches de espinafre e feta dourando em uma forma escura dentro do forno.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-06.webp"},{"title":"Deixe descansar","content":"Deixe as quiches na forma sobre uma grade por 10 minutos. O descanso firma o recheio e ajuda a soltar as bases sem quebrar a massa.","image_alt":"Doze miniquiches assadas descansando na forma sobre uma grade metálica.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-07.webp"},{"title":"Sirva as quiches","content":"Sirva as miniquiches mornas, com duas unidades por porção. O recheio deve estar firme e suculento, e a massa dourada também no fundo.","image_alt":"Miniquiches douradas em um prato de cerâmica creme, uma aberta mostrando espinafre e feta cozidos.","image_url":"/recetas/mini-quiches-de-espinaca-y-queso-feta/paso-08.webp"}],"seo":{"faq":[{"a":"Sim. Use 150 g depois de descongelar e espremer. Esse é o peso do espinafre que entra no recheio, sem o líquido.","q":"Posso usar espinafre congelado?"},{"a":"Não para estas quiches pequenas. Use discos finos, recheio bem escorrido e o terço inferior do forno preaquecido.","q":"Preciso pré-assar a massa?"},{"a":"Espinafre mal espremido, massa grossa ou forno sem preaquecimento são causas comuns. Evite também encher as cavidades até a borda.","q":"Por que o fundo fica úmido?"}],"title":"Miniquiches de espinafre e feta com massa folhada","image_alt":"Miniquiches douradas em um prato de cerâmica creme, uma aberta mostrando espinafre e feta cozidos.","description":"Prepare 12 miniquiches de espinafre e feta com massa folhada dourada. Oito etapas com fotos, recheio cremoso e dicas de forno e conservação.","image_variants":["/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-1x1.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-4x3.webp","/recetas/mini-quiches-de-espinaca-y-queso-feta/portada-16x9.webp"]},"nutrition":{"note":"Estimativa para duas quiches; os valores variam com as marcas de massa, creme de leite e feta. Não inclui acompanhamentos.","fat_g":38.2,"method":"Soma dos nutrientes pelos pesos dos ingredientes, dividida por 6 porções; leite e creme de leite aproximados a 1 g/ml.","source":"USDA FoodData Central, SR Legacy, April 2018","carbs_g":27.2,"fiber_g":1.9,"sugar_g":2.2,"calories":499.6,"estimated":true,"protein_g":13,"sodium_mg":498.5,"source_url":"https://fdc.nal.usda.gov/","serving_size":"2 miniquiches (1/6 da receita)","saturated_fat_g":15.3},"notes":"<h3>Dicas</h3><p>Use discos de massa com cerca de 25 g e mantenha-os frios. Preaqueça o forno enquanto prepara o recheio. O feta já fornece sal. Por segurança alimentar, o recheio de ovos deve atingir 71 °C no centro.</p><h3>Substituições</h3><p>Você pode trocar o espinafre fresco por 150 g de espinafre congelado, pesado depois de descongelar e espremer muito bem. Queijo de cabra firme pode substituir o feta, mas a quantidade de sal muda.</p><h3>Conservação</h3><p>Leve à geladeira em recipiente fechado em até 2 horas, a 4 °C ou menos, por 3–4 dias. Reaqueça até 74 °C no centro; o forno ajuda a recuperar a crocância da massa.</p><p class=\"md-sources\">Fontes: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/eggs/shell-eggs-farm-table\">USDA FSIS</a>; <a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a>.</p><p>Deixe o espinafre escorrido amornar antes de misturá-lo aos ovos.</p>"}]$payload$::jsonb;
BEGIN
  PERFORM 1 FROM public.recipes WHERE recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid FOR UPDATE;
  SELECT count(*) INTO n FROM public.recipes r JOIN jsonb_to_recordset(expected) AS e(id uuid, language text, public_path text, updated_at timestamptz) ON r.id=e.id AND r.language=e.language AND r.public_path=e.public_path AND r.updated_at=e.updated_at WHERE r.recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid AND r.published=false;
  IF n <> 7 OR (SELECT count(*) FROM public.recipes WHERE recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid) <> 7 THEN RAISE EXCEPTION 'Estado inicial cambió; revisar antes de publicar'; END IF;
  UPDATE public.recipes r SET steps=e.steps, seo=e.seo, nutrition=e.nutrition, notes=e.notes, published=true, editorial_status='published' FROM jsonb_to_recordset(expected) AS e(id uuid, steps jsonb, seo jsonb, nutrition jsonb, notes text) WHERE r.id=e.id AND r.recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid;
  DELETE FROM public.content_redirects WHERE source_path IN (SELECT public_path FROM public.recipes WHERE recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid) AND status_code IN (302,307);
  SELECT count(*) INTO n FROM public.recipes WHERE recipe_group_id='9f31d294-05e2-418c-8801-09db0f42907f'::uuid AND published=true AND nutrition IS NOT NULL;
  IF n <> 7 THEN RAISE EXCEPTION 'Publicación incompleta'; END IF;
END $block$;
COMMIT;
